declare(strict_types=1);
return [
"CREATE TABLE IF NOT EXISTS supervisors (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, display_name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('admin','supervisor') NOT NULL DEFAULT 'supervisor', active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, last_login_at DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
"CREATE TABLE IF NOT EXISTS contributors (participant_id VARCHAR(80) PRIMARY KEY, status VARCHAR(40) NOT NULL DEFAULT 'unknown', contributor_type VARCHAR(20) NOT NULL DEFAULT 'real', batch VARCHAR(80) NULL, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_contributor_type (contributor_type)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
"CREATE TABLE IF NOT EXISTS recordings (id BIGINT UNSIGNED PRIMARY KEY, participant_id VARCHAR(80) NOT NULL, duration_ms BIGINT UNSIGNED NULL, file_status VARCHAR(40) NOT NULL DEFAULT 'unknown', qc_status VARCHAR(30) NOT NULL DEFAULT 'pending', qc_reason VARCHAR(150) NULL, prompt_type VARCHAR(48) NULL, human_decision VARCHAR(10) NULL, human_operation_key CHAR(36) NULL, human_reviewed_at DATETIME NULL, qc_tier2 TINYINT UNSIGNED NULL, qc_tier3 VARCHAR(10) NULL, qc_tier3_reason VARCHAR(80) NULL, qc_final VARCHAR(12) NULL, band_reason VARCHAR(200) NULL, source_updated_at DATETIME(6) NULL, received_at DATETIME NOT NULL, is_test TINYINT(1) NOT NULL DEFAULT 0, duplicate_of BIGINT UNSIGNED NULL, imported_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_rec_date (received_at), INDEX idx_rec_contributor (participant_id), INDEX idx_rec_qc (qc_status,received_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
"CREATE TABLE IF NOT EXISTS supervisor_assignments (supervisor_id INT UNSIGNED NOT NULL, participant_id VARCHAR(80) NOT NULL, assigned_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(supervisor_id,participant_id), CONSTRAINT fk_as_user FOREIGN KEY (supervisor_id) REFERENCES supervisors(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
