"CREATE TABLE IF NOT EXISTS followups (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, recording_id BIGINT UNSIGNED NOT NULL, created_by INT UNSIGNED NOT NULL, state ENUM('open','resolved','reopened') NOT NULL DEFAULT 'open', notes TEXT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_followup_recording (recording_id,created_at), CONSTRAINT fk_follow_user FOREIGN KEY (created_by) REFERENCES supervisors(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
"CREATE TABLE IF NOT EXISTS notification_state (user_id INT UNSIGNED PRIMARY KEY, last_seen_recording_id BIGINT UNSIGNED NOT NULL DEFAULT 0, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_notif_user FOREIGN KEY (user_id) REFERENCES supervisors(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
"CREATE TABLE IF NOT EXISTS app_settings (setting_key VARCHAR(100) PRIMARY KEY, setting_value LONGTEXT NOT NULL, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
"CREATE TABLE IF NOT EXISTS sync_runs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, status ENUM('ok','failed') NOT NULL, description VARCHAR(500) NOT NULL, started_at DATETIME NOT NULL, finished_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
"CREATE TABLE IF NOT EXISTS login_attempts (ip_digest CHAR(64) PRIMARY KEY, attempts INT UNSIGNED NOT NULL DEFAULT 0, window_started DATETIME NOT NULL, locked_until DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
"CREATE TABLE IF NOT EXISTS audit_log (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, actor_id INT UNSIGNED NULL, action VARCHAR(70) NOT NULL, subject_type VARCHAR(35) NULL, subject_id VARCHAR(90) NULL, details VARCHAR(255) NOT NULL DEFAULT '', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_log_date (created_at), INDEX idx_log_actor (actor_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci"
